@helion.kernel(static_shapes=False)
def pure_collapse_sum(x: torch.Tensor) -> torch.Tensor:
    """PURE grid-origin M-collapse (no per-row work, body_live_tiles<=1): per-feature SUM over
    the batch/grid M axis via the two-level grid loop (unbacked inner re-tile ->
    grid_reduction_origin). The grid CTA block is occupancy-sized & capped at M_COLLAPSE_MAX_CTA;
    for a pure collapse r_block == m_collapse_block (the CTA block bears the whole slab)."""
    M, N = x.shape
    m_block = hl.register_block_size(M)
    nb = (M + m_block - 1) // m_block
    blocks = x.new_zeros([nb, N], dtype=torch.float32)
    for cta in hl.tile(M, block_size=m_block):
        acc = x.new_zeros([N], dtype=torch.float32)
        for mb in hl.tile(cta.begin, cta.end):
            acc = acc + torch.sum(x[mb, :].to(torch.float32), dim=0)
        blocks[cta.id, :] = acc
    return torch.sum(blocks, dim=0)


